-- Apteka Bober DWH: 03_views.sql (Аналитические витрины и представления)
USE `apteka_bober`;

CREATE OR REPLACE VIEW `v_ai_executive_navigator` AS select `l`.`store_id` AS `ID Аптеки`,`st`.`store_name` AS `Аптека`,`l`.`audit_reason` AS `Тип События`,count(0) AS `Количество за месяц`,(case when (`l`.`audit_reason` = 'PRICE_OBJECTION') then 'Пересмотреть наценку / Внести в LOCAL-маркеры (Слон 5)' when (`l`.`audit_reason` = 'QUEUE_PEAK') then 'КРИТИЧЕСКИЙ ТРАФИК: Выход заведующей на кассу / Пересмотр сменности' when (`l`.`audit_reason` = 'LOW_UX_SKILLS') then 'Слабые продажи: Направить сотрудника на скрипты / Очный тренинг' when (`l`.`audit_reason` = 'DEFECTURA') then 'Мертвая зона: Превентивно расширить Мин-Макс (Слон 3) / Закуп Ривароксабана' when (`l`.`audit_reason` = 'NO_RECIPE') then 'Рецептурный отказ: Норматив РФ соблюден, действия не требуются' else 'Игнорировать: Внекоммерческий шум торгового зала' end) AS `Рекомендация системе`,max(`l`.`log_timestamp`) AS `Последняя фиксация` from (`ai_omni_audit_log` `l` join `stores` `st` on((`st`.`store_id` = `l`.`store_id`))) group by `l`.`store_id`,`st`.`store_name`,`l`.`audit_reason`;

CREATE OR REPLACE VIEW `v_ai_recommendations` AS select `a`.`store_id` AS `store_id`,`a`.`goods_id` AS `goods_id`,`g`.`goods_name` AS `goods_name`,`a`.`rejection_reason` AS `rejection_reason`,count(0) AS `fail_count`,(case when ((`a`.`rejection_reason` = 'PRICE') and (count(0) > 3)) then 'Добавить в LOCAL-маркеры (Слон 5) и снизить цену' when ((`a`.`rejection_reason` = 'OUT_OF_STOCK') and (count(0) > 3)) then 'Увеличить Мин-Макс (Слон 3), товар в дефиците' when (`a`.`rejection_reason` = 'QUEUE') then 'Риск: Нехватка персонала в часы пик (Слон 7)' when (`a`.`rejection_reason` = 'INCOMPETENCE') then 'Обучить персонал: недостаточно знаний по товару' else 'Проанализировать вручную' end) AS `recommendation` from (`ai_demand_log` `a` join `goods` `g` on((`g`.`goods_id` = `a`.`goods_id`))) group by `a`.`store_id`,`a`.`goods_id`,`g`.`goods_name`,`a`.`rejection_reason` having (count(0) > 0);

CREATE OR REPLACE VIEW `v_all_valid_declines` AS select `lost_demand_log`.`store_id` AS `store_id`,`lost_demand_log`.`goods_id` AS `goods_id`,`lost_demand_log`.`scan_timestamp` AS `scan_timestamp`,`lost_demand_log`.`lost_qty` AS `lost_qty`,'MANUAL' AS `source_type`,NULL AS `rejection_reason` from `lost_demand_log` where (`lost_demand_log`.`validation_status` = 'VALID') union all select `ai_demand_log`.`store_id` AS `store_id`,`ai_demand_log`.`goods_id` AS `goods_id`,`ai_demand_log`.`scan_timestamp` AS `scan_timestamp`,`ai_demand_log`.`lost_qty` AS `lost_qty`,'AI_VOICE' AS `source_type`,`ai_demand_log`.`rejection_reason` AS `rejection_reason` from `ai_demand_log`;

CREATE OR REPLACE VIEW `v_cash_register_scan` AS select `g`.`goods_id` AS `goods_id`,`g`.`goods_name` AS `goods_name`,`g`.`is_prescription` AS `is_prescription`,(case when (`g`.`is_prescription` = 1) then 'ВНИМАНИЕ: ТРЕБУЕТСЯ РЕЦЕПТ! ПРОВЕРЬТЕ БЛАНК!' else 'Продажа разрешена (Безрецептурный отпуск)' end) AS `rx_alert_message` from `goods` `g`;

CREATE OR REPLACE VIEW `v_employee_daily_salary` AS with `store_staff_counts` as (select `employees`.`store_id` AS `store_id`,count(0) AS `pharmacists_count` from `employees` where ((`employees`.`is_active` = 1) and (`employees`.`position` = 'PHARMACIST')) group by `employees`.`store_id`) select `s`.`sale_date` AS `Дата смены`,`s`.`store_id` AS `ID Аптеки`,`st`.`store_name` AS `Аптека`,`s`.`employee_id` AS `ID Сотрудника`,concat(`e`.`last_name`,' ',substr(`e`.`first_name`,1,1),'.',(case when (`e`.`middle_name` is not null) then concat(substr(`e`.`middle_name`,1,1),'.') else '' end)) AS `Сотрудник`,(to_days(`s`.`sale_date`) - to_days(`e`.`hire_date`)) AS `Стаж (дней)`,count(distinct `s`.`sale_datetime`) AS `Факт КЧ (чеков)`,round(sum((`s`.`qty` * `s`.`retail_price`)),2) AS `Выручка дня (руб)`,round(sum((`s`.`qty` * (`s`.`retail_price` - `s`.`purchase_price`))),2) AS `Личная маржа (руб)`,round(greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))),2) AS `Коэф ТО`,round(greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0)))),2) AS `Коэф КЧ`,round((case when ((to_days(`s`.`sale_date`) - to_days(`e`.`hire_date`)) < 90) then greatest(1.0,((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2)) else ((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2) end),2) AS `Итоговый коэф оклада`,round((sum((`s`.`qty` * (`s`.`retail_price` - `s`.`purchase_price`))) * 0.12),2) AS `Премия 12% маржи (руб)`,round(((`st`.`norm_per_shift_rub` * (case when ((to_days(`s`.`sale_date`) - to_days(`e`.`hire_date`)) < 90) then greatest(1.0,((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2)) else ((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2) end)) + (sum((`s`.`qty` * (`s`.`retail_price` - `s`.`purchase_price`))) * 0.12)),2) AS `Начислено грязными (руб)`,round((((`st`.`norm_per_shift_rub` * (case when ((to_days(`s`.`sale_date`) - to_days(`e`.`hire_date`)) < 90) then greatest(1.0,((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2)) else ((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2) end)) + (sum((`s`.`qty` * (`s`.`retail_price` - `s`.`purchase_price`))) * 0.12)) * 0.87),2) AS `ЗП чистыми (руб)` from (((`sales` `s` join `employees` `e` on((`e`.`employee_id` = `s`.`employee_id`))) join `stores` `st` on((`st`.`store_id` = `s`.`store_id`))) left join `store_staff_counts` `ssc` on((`ssc`.`store_id` = `st`.`store_id`))) where ((`e`.`is_active` = 1) and (`e`.`position` = 'PHARMACIST')) group by `s`.`sale_date`,`s`.`store_id`,`st`.`store_name`,`s`.`employee_id`,`e`.`last_name`,`e`.`first_name`,`e`.`middle_name`,`e`.`hire_date`,`st`.`daily_to_plan_rub`,`st`.`daily_checks_plan`,`st`.`norm_per_shift_rub`,`ssc`.`pharmacists_count`;

CREATE OR REPLACE VIEW `v_payroll_ready` AS select `s`.`store_id` AS `store_id`,`s`.`store_name` AS `store_name`,count(`w`.`writeoff_id`) AS `undistributed_writeoffs`,coalesce(sum(`w`.`loss_amount`),0) AS `blocked_amount`,if((count(`w`.`writeoff_id`) = 0),'READY','BLOCKED') AS `payroll_status` from (`stores` `s` left join `expiry_writeoffs` `w` on(((`w`.`store_id` = `s`.`store_id`) and (`w`.`penalty_distributed` = 0)))) group by `s`.`store_id`,`s`.`store_name`;

CREATE OR REPLACE VIEW `v_personal_offers` AS select `b`.`store_id` AS `store_id`,`pr`.`trigger_goods_id` AS `trigger_goods_id`,`pr`.`offer_goods_id` AS `offer_goods_id`,`g_offer`.`goods_name` AS `offer_goods_name`,`g_offer`.`matrix_status` AS `matrix_status`,`pr`.`promo_type` AS `promo_type`,`pr`.`discount_pct` AS `discount_pct`,`b`.`retail_price` AS `price_before`,round((`b`.`retail_price` * (1 - (`pr`.`discount_pct` / 100))),2) AS `price_after`,round((`b`.`retail_price` * (`pr`.`discount_pct` / 100)),2) AS `benefit_rub`,(case when (`g_offer`.`matrix_status` = 'ZNVLP') then `b`.`purchase_price` else round((`b`.`purchase_price` * (1 + (`pr`.`min_markup_guard` / 100))),2) end) AS `dynamic_floor_price` from ((`promo_rules` `pr` join `goods` `g_offer` on((`g_offer`.`goods_id` = `pr`.`offer_goods_id`))) join `goods_batches` `b` on(((`b`.`goods_id` = `pr`.`offer_goods_id`) and (`b`.`qty` > 0)))) where ((`pr`.`is_active` = 1) and (round((`b`.`retail_price` * (1 - (`pr`.`discount_pct` / 100))),2) >= (case when (`g_offer`.`matrix_status` = 'ZNVLP') then `b`.`purchase_price` else round((`b`.`purchase_price` * (1 + (`pr`.`min_markup_guard` / 100))),2) end)));

CREATE OR REPLACE VIEW `v_stock_quality` AS select `v_stock_status`.`store_id` AS `store_id`,round(sum(`v_stock_status`.`stock_value_purchase_net`),2) AS `tz_rub_net`,round(((sum((case when (`v_stock_status`.`stock_status` = 'LIQUID') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `liquid_pct`,round(((sum((case when (`v_stock_status`.`stock_status` = 'SURPLUS') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `surplus_pct`,round(((sum((case when (`v_stock_status`.`stock_status` = 'DEAD_STOCK') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `bad_pct`,round(((sum((case when (`v_stock_status`.`stock_status` = 'EXPIRING') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `expiring_pct`,round(((sum((case when (`v_stock_status`.`stock_status` = 'SUSPECT_STAGNATION') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `suspicious_pct`,round(((sum((case when (`v_stock_status`.`stock_status` = 'INCUBATION') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `incubation_pct` from `v_stock_status` group by `v_stock_status`.`store_id`;

CREATE OR REPLACE VIEW `v_stock_status` AS select `b`.`store_id` AS `store_id`,`b`.`goods_id` AS `goods_id`,`g`.`goods_name` AS `goods_name`,`g`.`group_id` AS `group_id`,`pg`.`group_name` AS `group_name`,`pg`.`shelf_life_days` AS `shelf_life_days`,sum(`b`.`qty`) AS `qty_total`,sum((case when (`b`.`batch_status` = 'IN_TRANSIT') then `b`.`qty` else 0 end)) AS `qty_in_transit`,sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`purchase_type` <> 'OFFICE_LOAD') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING')) then `b`.`qty` else 0 end)) AS `qty_net`,round(sum((`b`.`qty` * `b`.`purchase_price`)),2) AS `stock_value_purchase`,round(sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`purchase_type` <> 'OFFICE_LOAD') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING')) then (`b`.`qty` * `b`.`purchase_price`) else 0 end)),2) AS `stock_value_purchase_net`,round(sum((`b`.`qty` * `b`.`retail_price`)),2) AS `stock_value_retail`,round(sum((`b`.`qty` * ((`b`.`retail_price` - `b`.`purchase_price`) + (`b`.`purchase_price` * (`g`.`marketing_bonus_pct` / 100))))),2) AS `total_real_profit`,min(`b`.`expiry_date`) AS `nearest_expiry`,round(coalesce(((sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING')) then `b`.`qty` else 0 end)) / nullif(max(`s_hist`.`active_days_90`),0)) * 90),0),1) AS `sku_turnover_days`,`st`.`max_stagnation_multiplier` AS `max_stagnation_multiplier`,`st`.`absolute_dead_threshold_days` AS `absolute_dead_threshold_days`,(case when ((to_days(curdate()) - to_days(`st`.`opened_date`)) < 30) then 'INCUBATION' when (min(`b`.`expiry_date`) <= (curdate() + interval 3 month)) then 'EXPIRING' when exists(select 1 from `sales` `s_real` where ((`s_real`.`store_id` = `b`.`store_id`) and (`s_real`.`goods_id` = `b`.`goods_id`) and (`s_real`.`sale_date` >= (curdate() - interval 30 day)))) then 'LIQUID' when (max(`b`.`is_returned_dead`) = 1) then 'DEAD_STOCK' when ((not exists(select 1 from `goods_batches` `b_old` where ((`b_old`.`store_id` = `b`.`store_id`) and (`b_old`.`goods_id` = `b`.`goods_id`) and (`b_old`.`received_at` < max(`b`.`received_at`)) and (`b_old`.`received_at` >= (max(`b`.`received_at`) - interval 365 day))))) and (max(`b`.`received_at`) <= (curdate() - interval 180 day)) and (not exists(select 1 from `sales` `s_nov` where ((`s_nov`.`store_id` = `b`.`store_id`) and (`s_nov`.`goods_id` = `b`.`goods_id`) and (`s_nov`.`sale_date` >= max(`b`.`received_at`)))))) then 'DEAD_STOCK' when ((not exists(select 1 from `sales` `s2` where ((`s2`.`store_id` = `b`.`store_id`) and (`s2`.`goods_id` = `b`.`goods_id`) and (`s2`.`sale_date` >= (curdate() - interval `pg`.`shelf_life_days` day))))) and (max(`b`.`received_at`) <= (curdate() - interval `pg`.`shelf_life_days` day))) then 'DEAD_STOCK' when ((coalesce((select `mm`.`effective_max` from `min_max` `mm` where ((`mm`.`store_id` = `b`.`store_id`) and (`mm`.`goods_id` = `b`.`goods_id`)) order by `mm`.`calc_date` desc limit 1),0) > 0) and (sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`purchase_type` <> 'OFFICE_LOAD') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING')) then `b`.`qty` else 0 end)) > (select `mm`.`effective_max` from `min_max` `mm` where ((`mm`.`store_id` = `b`.`store_id`) and (`mm`.`goods_id` = `b`.`goods_id`)) order by `mm`.`calc_date` desc limit 1))) then 'SURPLUS' when ((round((coalesce(((sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING')) then `b`.`qty` else 0 end)) / nullif(max(`s_hist`.`active_days_90`),0)) * 90),0) * `st`.`max_stagnation_multiplier`),0) > 0) and (max(`b`.`received_at`) <= (curdate() - interval round((coalesce(((sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING')) then `b`.`qty` else 0 end)) / nullif(max(`s_hist`.`active_days_90`),0)) * 90),0) * `st`.`max_stagnation_multiplier`),0) day)) and exists(select 1 from `goods_batches` `b_old2` where ((`b_old2`.`store_id` = `b`.`store_id`) and (`b_old2`.`goods_id` = `b`.`goods_id`) and (`b_old2`.`received_at` < max(`b`.`received_at`)) and (`b_old2`.`received_at` >= (max(`b`.`received_at`) - interval 365 day))))) then 'SUSPECT_STAGNATION' else 'LIQUID' end) AS `stock_status` from ((((`goods_batches` `b` join `goods` `g` on((`g`.`goods_id` = `b`.`goods_id`))) join `pharm_groups` `pg` on((`pg`.`group_id` = `g`.`group_id`))) join `stores` `st` on((`st`.`store_id` = `b`.`store_id`))) left join (select `sales`.`store_id` AS `store_id`,`sales`.`goods_id` AS `goods_id`,count(distinct `sales`.`sale_date`) AS `active_days_90` from `sales` where (`sales`.`sale_date` >= (curdate() - interval 90 day)) group by `sales`.`store_id`,`sales`.`goods_id`) `s_hist` on(((`s_hist`.`store_id` = `b`.`store_id`) and (`s_hist`.`goods_id` = `b`.`goods_id`)))) where (`b`.`qty` > 0) group by `b`.`store_id`,`b`.`goods_id`,`g`.`goods_name`,`g`.`group_id`,`pg`.`group_name`,`pg`.`shelf_life_days`,`st`.`opened_date`,`st`.`max_stagnation_multiplier`,`st`.`absolute_dead_threshold_days`,`g`.`marketing_bonus_pct`;

CREATE OR REPLACE VIEW `v_viability_live` AS select `st`.`store_id` AS `store_id`,curdate() AS `snapshot_date`,coalesce(`past`.`to_past`,0) AS `to_past`,coalesce(`past`.`margin_past`,0) AS `margin_past_rub`,round(((coalesce(`past`.`to_past`,0) / nullif(`fc`.`plan_to`,0)) * 100),2) AS `plan_exec_past_pct`,coalesce(`cur`.`to_cur`,0) AS `to_current`,coalesce(`cur`.`margin_cur`,0) AS `margin_current_rub`,coalesce(`cur`.`upch`,0) AS `upch`,coalesce(`cur`.`sch`,0) AS `sch`,coalesce(`q`.`tz_rub_net`,0) AS `tz_rub`,coalesce(`q`.`liquid_pct`,0) AS `liquid_share_pct`,coalesce(`q`.`surplus_pct`,0) AS `surplus_share_pct`,coalesce(`q`.`bad_pct`,0) AS `bad_stock_share_pct`,coalesce(`q`.`expiring_pct`,0) AS `expiring_share_pct`,coalesce(`lp`.`lost_margin_sum`,0) AS `lost_profit_rub`,round(if((dayofmonth(curdate()) < 5),coalesce(`fc`.`plan_to`,0),((coalesce(`cur`.`to_cur`,0) / dayofmonth(curdate())) * dayofmonth(last_day(curdate())))),2) AS `to_forecast`,round(if((dayofmonth(curdate()) < 5),100.00,((((coalesce(`cur`.`to_cur`,0) / dayofmonth(curdate())) * dayofmonth(last_day(curdate()))) / nullif(`fc`.`plan_to`,0)) * 100)),2) AS `plan_gap_pct`,(case when ((to_days(curdate()) - to_days(`st`.`opened_date`)) < 30) then 'INCUBATION' when ((coalesce(`lp`.`lost_margin_sum`,0) > (coalesce(`cur`.`to_cur`,0) * 0.15)) and (coalesce(`cur`.`margin_cur`,0) < (coalesce(`fc`.`rent_cost`,0) + coalesce(`fc`.`fot_cost`,0)))) then 'CLOSURE' when ((round(if((dayofmonth(curdate()) < 5),100.00,((((coalesce(`cur`.`to_cur`,0) / dayofmonth(curdate())) * dayofmonth(last_day(curdate()))) / nullif(`fc`.`plan_to`,0)) * 100)),2) > 95) and (coalesce(`q`.`liquid_pct`,0) >= 65)) then 'RENTABLE' else 'RISK_ZONE' end) AS `viability_marker`,(case when ((to_days(curdate()) - to_days(`st`.`opened_date`)) < 30) then 'Стадия раскачки нового объекта' when (coalesce(`lp`.`lost_margin_sum`,0) > (coalesce(`cur`.`to_cur`,0) * 0.15)) then 'Упущенная выгода > 15%' else NULL end) AS `marker_comment` from (((((`stores` `st` left join `pharmacy_fixed_costs` `fc` on(((`fc`.`store_id` = `st`.`store_id`) and (`fc`.`period` = date_format(curdate(),'%Y-%m-01'))))) left join (select `sales`.`store_id` AS `store_id`,sum((`sales`.`qty` * `sales`.`retail_price`)) AS `to_past`,sum((`sales`.`qty` * (`sales`.`retail_price` - `sales`.`purchase_price`))) AS `margin_past` from `sales` where (`sales`.`sale_date` between (date_format(curdate(),'%Y-%m-01') - interval 1 month) and (date_format(curdate(),'%Y-%m-01') - interval 1 day)) group by `sales`.`store_id`) `past` on((`past`.`store_id` = `st`.`store_id`))) left join (select `sales`.`store_id` AS `store_id`,sum((`sales`.`qty` * `sales`.`retail_price`)) AS `to_cur`,sum((`sales`.`qty` * (`sales`.`retail_price` - `sales`.`purchase_price`))) AS `margin_cur`,round((sum(`sales`.`qty`) / nullif(count(distinct `sales`.`sale_datetime`),0)),2) AS `upch`,round((sum((`sales`.`qty` * `sales`.`retail_price`)) / nullif(count(distinct `sales`.`sale_datetime`),0)),2) AS `sch` from `sales` where (`sales`.`sale_date` between date_format(curdate(),'%Y-%m-01') and curdate()) group by `sales`.`store_id`) `cur` on((`cur`.`store_id` = `st`.`store_id`))) left join `v_stock_quality` `q` on((`q`.`store_id` = `st`.`store_id`))) left join (select `lost_profit_log`.`store_id` AS `store_id`,sum(`lost_profit_log`.`lost_margin`) AS `lost_margin_sum` from `lost_profit_log` where ((`lost_profit_log`.`calc_date` between date_format(curdate(),'%Y-%m-01') and curdate()) and (`lost_profit_log`.`reason_code` <> 'EXPIRED_WRITEOFF')) group by `lost_profit_log`.`store_id`) `lp` on((`lp`.`store_id` = `st`.`store_id`))) where (`st`.`is_active` = 1);

